/**
 * Map layers and area statistics, generated by `node scripts/build-data.mjs`.
 */
import floodZones from "./generated/flood-zones.json";
import localitiesRaw from "./generated/localities.json";
import poisRaw from "./generated/pois.json";
import priceGridRaw from "./generated/price-grid.json";
import type { PoiCategory } from "./listings";

export interface Poi {
  id: string;
  name: string;
  category: PoiCategory;
  coords: [number, number];
  major?: boolean;
  status?: "under_construction";
}

export interface Locality {
  name: string;
  city: string;
  district: string;
  coords: [number, number];
  /** Indicative asking price per sq.ft (demo). */
  psf: number;
  landPerCent: number;
  yoy: number;
  listingCount: number;
  nearby: Partial<Record<"metro" | "it_park" | "water_metro", { name: string; km: number; status?: "under_construction" } | null>>;
  schools2km: number;
}

export const pois = poisRaw as Poi[];
export const localities = localitiesRaw as Locality[];
export { floodZones };

/** Price heat points: [lng, lat, psf]. */
export const priceGrid = priceGridRaw.rows as unknown as [number, number, number][];

export const POI_LABEL: Record<PoiCategory, string> = {
  metro: "Metro",
  water_metro: "Water Metro",
  rail: "Railway",
  it_park: "IT park",
  hospital: "Hospital",
  school: "School",
  college: "College",
  mall: "Mall",
  bus: "Bus station",
  airport: "Airport",
};
